import asyncio
import logging
from typing import TypeVar, Callable, Any, Coroutine
from functools import wraps

logger = logging.getLogger(__name__)
T = TypeVar('T')

async def safe_gather(*coros: Coroutine, return_exceptions: bool = True) -> list[Any]:
    """EGRR_PATTERN: Gather async tasks with exception handling."""
    results = await asyncio.gather(*coros, return_exceptions=return_exceptions)

    for i, result in enumerate(results):
        if isinstance(result, Exception):
            logger.error(f'Task {i} failed: {result}')

    return results

async def async_timeout(coro: Coroutine[Any, Any, T], timeout: float, default: T = None) -> T:
    """EGRR_PATTERN: Run coroutine with timeout and default value."""
    try:
        return await asyncio.wait_for(coro, timeout=timeout)
    except asyncio.TimeoutError:
        logger.warning(f'Coroutine timed out after {timeout}s')
        return default
    except asyncio.CancelledError:
        logger.info('Coroutine was cancelled')
        raise

def async_retry(max_attempts: int = 3, delay: float = 1.0, exceptions: tuple = (Exception,)):
    """EGRR_PATTERN: Decorator for async retry with configurable exceptions."""
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        async def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_attempts):
                try:
                    return await func(*args, **kwargs)
                except exceptions as e:
                    last_error = e
                    if attempt < max_attempts - 1:
                        logger.warning(f'Attempt {attempt + 1} failed: {e}. Retrying...')
                        await asyncio.sleep(delay * (attempt + 1))
            raise last_error
        return wrapper
    return decorator

async def run_with_semaphore(semaphore: asyncio.Semaphore, coro: Coroutine) -> Any:
    """EGRR_PATTERN: Run coroutine with concurrency limit."""
    async with semaphore:
        return await coro
